public class Detect {
    static String family(String name) {
        if (name.startsWith("G1")) {
            return "G1";
        }
        if (name.startsWith("PS")) {
            return "Parallel";
        }
        if (name.equals("Copy")) {
            return "Serial";
        }
        return "Other";
    }

    public static void main(String[] args) {
        System.out.println(family("G1 Young Generation") + "," + family("PS Scavenge") + "," + family("ZGC"));
    }
}

